  <div class="problem-strip">
    <div><b>已知</b>：f(x) = e<sup>x</sup> − a x − 3，a ∈ R。</div>
    <div><b>(1)</b> x ≥ 0 时，f(x) ≥ x<sup>2</sup>/2 − 2 恒成立，求 a 的范围。</div>
    <div><b>(2)</b> f(x) 有两个零点 x<sub>1</sub> &lt; x<sub>2</sub>：(i) 求 a 的范围；(ii) 证明 3e<sup>x<sub>1</sub></sup> + e<sup>x<sub>2</sub></sup> &gt; 3a。</div>
  </div>

  <div class="steps" id="stepTabs">
    <button class="step-btn active" data-step="0">1 转化</button>
    <button class="step-btn" data-step="1">2 g 的走向</button>
    <button class="step-btn" data-step="2">3 两根条件</button>
    <button class="step-btn" data-step="3">4 移位</button>
    <button class="step-btn" data-step="4">5 证明</button>
  </div>

  <div class="main">
    <section class="panel viz-panel">
      <div class="svg-wrap">
        <svg id="mainSvg" viewBox="0 0 760 520" role="img" aria-label="数学交互图形"></svg>
      </div>
      <div class="controls">
        <div class="control-label" id="sliderLabel">参数 a</div>
        <input id="slider" type="range" min="0.2" max="1.8" step="0.01" value="0.8">
        <div class="value-pill" id="sliderValue">0.80</div>
        <button class="btn primary" id="quickBtn">a=1 边界</button>
        <button class="btn" id="resetBtn">复位</button>
      </div>
      <div class="answers">
        <div class="ans locked" id="ans1"><span>第 (1) 问结论</span><b>a ≤ 1</b></div>
        <div class="ans locked" id="ans2"><span>第 (2)(i) 结论</span><b>a &gt; 0</b></div>
        <div class="ans locked" id="ans3"><span>第 (2)(ii) 结论</span><b>3e<sup>x<sub>1</sub></sup> + e<sup>x<sub>2</sub></sup> &gt; 3a</b></div>
      </div>
    </section>

    <aside class="panel side-card" id="sideCard"></aside>
  </div>
</div>

<script>
const state = { step: 0, a1: 0.8, a2: 1.5, r: 3.0 };
const DEFAULTS = { a1: 0.8, a2: 1.5, r: 3.0 };

const svgEl = document.getElementById('mainSvg');
const sideEl = document.getElementById('sideCard');
const slider = document.getElementById('slider');
const sliderLabel = document.getElementById('sliderLabel');
const sliderValue = document.getElementById('sliderValue');
const quickBtn = document.getElementById('quickBtn');
const resetBtn = document.getElementById('resetBtn');

function clamp(v, lo, hi){ return Math.max(lo, Math.min(hi, v)); }
function fmt(v, d=2){
  if (!isFinite(v)) return '—';
  if (Math.abs(v) < 0.00005 && Math.abs(v) > 0) return v.toExponential(1);
  if (Math.abs(v) >= 1000) return v.toFixed(0);
  let s = v.toFixed(d);
  s = s.replace(/\.0+$/, '').replace(/(\.\d*?)0+$/, '$1');
  return s;
}
function niceStep(x){
  if (!isFinite(x) || x <= 0) return 1;
  const p = Math.pow(10, Math.floor(Math.log10(x)));
  const r = x / p;
  if (r < 1.5) return p;
  if (r < 3) return 2 * p;
  if (r < 7) return 5 * p;
  return 10 * p;
}
function makeTicks(min, max, count=6){
  const step = niceStep((max - min) / Math.max(2, count));
  let start = Math.ceil((min - 1e-9) / step) * step;
  const arr = [];
  for (let v = start; v <= max + 1e-9; v += step) {
    if (Math.abs(v) < 1e-9) v = 0;
    arr.push(Number(v.toFixed(10)));
  }
  return arr;
}
function lineEl(x1,y1,x2,y2,color,w=1,dash='',opacity=1){
  return `<line x1="${x1.toFixed(2)}" y1="${y1.toFixed(2)}" x2="${x2.toFixed(2)}" y2="${y2.toFixed(2)}" stroke="${color}" stroke-width="${w}" ${dash ? `stroke-dasharray="${dash}"` : ''} opacity="${opacity}" stroke-linecap="round"/>`;
}
function txt(x,y,text,fill='#253047',opts={}){
  const size = opts.size || 13;
  const anchor = opts.anchor || 'start';
  const weight = opts.weight || 500;
  const stroke = opts.stroke === false ? 0 : 3;
  return `<text x="${x.toFixed(2)}" y="${y.toFixed(2)}" font-size="${size}" font-weight="${weight}" fill="${fill}" text-anchor="${anchor}" paint-order="stroke" stroke="#ffffff" stroke-width="${stroke}" stroke-linejoin="round">${text}</text>`;
}
function circleEl(cx,cy,r,fill,stroke='#ffffff',sw=2){
  return `<circle cx="${cx.toFixed(2)}" cy="${cy.toFixed(2)}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>`;
}
function svgBadge(x,y,text,color='#166534',bg='#dcfce7'){
  const w = Math.max(136, text.length * 14 + 26);
  return `<g><rect x="${x.toFixed(2)}" y="${(y-19).toFixed(2)}" width="${w}" height="31" rx="15.5" fill="${bg}" stroke="${color}" stroke-opacity=".28"/><text x="${(x+w/2).toFixed(2)}" y="${(y+3).toFixed(2)}" text-anchor="middle" font-size="13" font-weight="750" fill="${color}">${text}</text></g>`;
}
function pathFor(fn, X, Y, x0, x1, N, attrs){
  let d = '';
  let started = false;
  for (let i = 0; i <= N; i++) {
    const x = x0 + (x1 - x0) * i / N;
    const y = fn(x);
    if (!isFinite(y)) continue;
    const sx = X(x);
    const sy = Y(y);
    d += (started ? ' L' : 'M') + sx.toFixed(2) + ' ' + sy.toFixed(2);
    started = true;
  }
  return `<path d="${d}" fill="none" ${attrs}/>`;
}
function bisect(fn, lo, hi, iters=70){
  let flo = fn(lo);
  let fhi = fn(hi);
  if (!isFinite(flo) || !isFinite(fhi)) return null;
  if (Math.abs(flo) < 1e-12) return lo;
  if (Math.abs(fhi) < 1e-12) return hi;
  if (flo * fhi > 0) return null;
  for (let i = 0; i < iters; i++) {
    const mid = (lo + hi) / 2;
    const fm = fn(mid);
    if (Math.abs(fm) < 1e-13) return mid;
    if (flo * fm <= 0) {
      hi = mid;
      fhi = fm;
    } else {
      lo = mid;
      flo = fm;
    }
  }
  return (lo + hi) / 2;
}

function frame(cfg){
  const L = 76, R = 716, T = 44, B = 472;
  const W = R - L, H = B - T;
  const { xMin, xMax, yMin, yMax } = cfg;
  const X = x => L + (x - xMin) / (xMax - xMin) * W;
  const Y = y => T + (yMax - y) / (yMax - yMin) * H;
  const xTicks = cfg.xTicks || makeTicks(xMin, xMax, 7);
  const yTicks = cfg.yTicks || makeTicks(yMin, yMax, 6);

  let s = '';
  s += `<rect x="0" y="0" width="760" height="520" fill="#ffffff"/>`;
  s += `<defs><clipPath id="plotClip"><rect x="${L}" y="${T}" width="${W}" height="${H}" rx="4"/></clipPath></defs>`;
  s += `<rect x="${L}" y="${T}" width="${W}" height="${H}" fill="#fbfdff"/>`;

  for (const x of xTicks) {
    const px = X(x);
    if (px < L - 2 || px > R + 2) continue;
    s += lineEl(px, T, px, B, '#e6edf6', 1);
    s += txt(px, B + 18, fmt(x, 2), '#64748b', { size: 11, anchor: 'middle', stroke: false });
  }
  for (const y of yTicks) {
    const py = Y(y);
    if (py < T - 2 || py > B + 2) continue;
    s += lineEl(L, py, R, py, '#e6edf6', 1);
    s += txt(L - 10, py + 4, fmt(y, 2), '#64748b', { size: 11, anchor: 'end', stroke: false });
  }

  s += `<rect x="${L}" y="${T}" width="${W}" height="${H}" fill="none" stroke="#cbd5e1" stroke-width="1.2"/>`;

  if (xMin <= 0 && 0 <= xMax) {
    s += lineEl(X(0), T, X(0), B, '#94a3b8', 1.5);
  }
  if (yMin <= 0 && 0 <= yMax) {
    s += lineEl(L, Y(0), R, Y(0), '#94a3b8', 1.5);
  }

  return { svg: s, X, Y, L, R, T, B, W, H };
}

function renderPart1(step){
  const a = state.a1;
  const g = x => (Math.exp(x) - 1) / x - x / 2;
  const cfg = {
    xMin: 0, xMax: 2.8, yMin: 0, yMax: 3.75,
    xTicks: [0, 0.5, 1, 1.5, 2, 2.5],
    yTicks: [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5]
  };
  const F = frame(cfg);
  let s = F.svg;

  const xCross = a > 1 ? bisect(x => g(x) - a, 0.0001, 2.8) : null;

  if (xCross !== null) {
    s += `<rect x="${F.L}" y="${F.T}" width="${Math.max(0, F.X(xCross)-F.L)}" height="${F.H}" fill="#ef4444" opacity="0.085" clip-path="url(#plotClip)"/>`;
  }

  s += txt(F.L + 8, F.T - 14, step === 0 ? '把恒成立化成 a 与 g(x) 的比较' : 'g(x) 从 1 向上增长', '#0f172a', { size: 16, weight: 800, stroke: false });

  s += lineEl(F.L, F.Y(1), F.R, F.Y(1), '#10b981', 1.8, '7 6');
  s += txt(F.X(0.12) + 4, F.Y(1) - 8, '极限值 1', '#047857', { size: 13, weight: 750 });

  s += pathFor(g, F.X, F.Y, 0.015, 2.8, 340,
    'stroke="#2563eb" stroke-width="3.2" clip-path="url(#plotClip)"');

  if (xCross !== null && xCross > 0.015) {
    s += pathFor(g, F.X, F.Y, 0.015, xCross, 100,
      'stroke="#dc2626" stroke-width="4.2" clip-path="url(#plotClip)"');
    s += circleEl(F.X(xCross), F.Y(a), 5, '#f97316');
    s += txt(F.X(xCross) + 7, F.Y(a) + 20, '交点', '#b45309', { size: 12.5, weight: 700 });
  }

  s += lineEl(F.L, F.Y(a), F.R, F.Y(a), '#f59e0b', 2.7, '9 5');
  s += txt(F.R - 8, F.Y(a) - 9, `当前 a = ${fmt(a,2)}`, '#b45309', { size: 14, weight: 800, anchor: 'end' });

  const lx = 1.62;
  s += txt(F.X(lx) + 10, F.Y(g(lx)) - 8, 'g(x)', '#1d4ed8', { size: 15, weight: 800 });

  const valid = a <= 1 + 1e-9;
  if (valid) {
    s += svgBadge(F.L + 18, F.T + 38, '全部 x>0：g(x) ≥ a', '#166534', '#dcfce7');
  } else {
    s += svgBadge(F.L + 18, F.T + 38, '靠近 0 处：g(x) < a', '#b91c1c', '#fee2e2');
  }

  if (step === 1) {
    s += txt(F.L + 18, F.B - 18, 'g′(x)>0（x>0），所以 g(x)>1', '#334155', { size: 14, weight: 700 });
  }

  s += circleEl(F.X(0) + 2, F.Y(1), 4.5, '#ffffff', '#10b981', 2.2);
  s += txt(F.R - 8, F.B + 34, 'x', '#475569', { size: 14, weight: 700, anchor: 'end' });
  s += txt(F.L - 44, F.T + 17, 'g', '#475569', { size: 14, weight: 700, anchor: 'middle' });

  let side = '';
  if (step === 0) {
    side = `
      <div class="kicker">第 (1) 问 · 转化</div>
      <h2>先把不等式移成“a 与一条曲线”的问题</h2>
      <div class="formula-box">
        <div class="formula-line">e<sup>x</sup> − ax − 3 ≥ x<sup>2</sup>/2 − 2</div>
        <div class="arrow-line">移项，在 x&gt;0 时两边除以 x：</div>
        <div class="formula-line highlight">a ≤ g(x) = (e<sup>x</sup> − 1)/x − x/2</div>
      </div>
      <p><b>x = 0</b> 时两边都是 −2，不给 a 增加限制。于是问题变成：橙线（当前 a）不能高过蓝线（g(x)）。</p>
      <div class="readout">
        <div class="readout-row"><span>当前 a</span><b>${fmt(a,2)}</b></div>
        <div class="readout-row"><span>是否全部满足</span><b class="${valid ? 'ok' : 'bad'}">${valid ? '是' : '否，靠近 0 处失败'}</b></div>
        <div class="readout-row"><span>临界位置</span><b>g(x) 趋近 1</b></div>
      </div>
      <p class="note">拖动滑块（下限 0.2 只是演示范围）：先观察橙线与蓝线在左端附近的高低关系；绿圈只表示 x→0+ 的极限位置，g(0) 无定义。临界值将在下一步由单调性确认。</p>
    `;
  } else {
    side = `
      <div class="kicker">第 (1) 问 · 结论</div>
      <h2>g(x) 从 1 开始单调上升</h2>
      <div class="formula-box">
        <div class="formula-line">g′(x) = [2e<sup>x</sup>(x−1)+2−x<sup>2</sup>]/(2x<sup>2</sup>)</div>
        <div class="formula-line">分子 N(x)=2e<sup>x</sup>(x−1)+2−x<sup>2</sup></div>
        <div class="formula-line highlight">N(0)=0，N′(x)=2x(e<sup>x</sup>−1)&gt;0 ⇒ g′(x)&gt;0</div>
      </div>
      <p>因此 x&gt;0 时 g(x) 始终大于左边的极限值 1。观察橙线：当 a 超过 1 时，蓝线左端会落到橙线下方；临界正是极限值 1。所以全部满足的条件是 a ≤ 1，且 a=1 时不等式也成立。</p>
      <div class="readout">
        <div class="readout-row"><span>当前 a</span><b>${fmt(a,2)}</b></div>
        <div class="readout-row"><span>所有 x&gt;0 均满足？</span><b class="${valid ? 'ok' : 'bad'}">${valid ? '是' : '否'}</b></div>
        <div class="readout-row"><span>最小下界</span><b>1（x→0<sup>+</sup>）</b></div>
      </div>
      <div class="conclusion">(1) a 的取值范围：a ≤ 1。</div>
    `;
  }
  return { svg: s, side };
}

function renderPart2(step){
  const a = state.a2;
  const f = x => Math.exp(x) - a * x - 3;
  const t = Math.log(a);
  const x1 = bisect(f, -1000, 0);
  const x2 = bisect(f, t, 100);
  const xMin = Math.min(-6, -3 / a - 2.5);
  const xMax = 4.5;

  const cfg = {
    xMin, xMax, yMin: -14, yMax: 24,
    xTicks: makeTicks(xMin, xMax, 7),
    yTicks: [-10, -5, 0, 5, 10, 15, 20]
  };
  const F = frame(cfg);
  let s = F.svg;

  s += txt(F.L + 8, F.T - 14, step === 2 ? 'f(x)=eˣ−ax−3 的极小值与零点' : '把两根相对 t=ln a 移位', '#0f172a', { size: 16, weight: 800, stroke: false });

  s += pathFor(f, F.X, F.Y, xMin, xMax, 420,
    'stroke="#2563eb" stroke-width="3.1" clip-path="url(#plotClip)"');

  const y0 = F.Y(0);
  const ft = f(t);
  s += lineEl(F.X(t), F.T, F.X(t), F.B, '#94a3b8', 1.2, '6 5');
  s += circleEl(F.X(t), F.Y(ft), 5.5, '#64748b');
  s += txt(F.X(t) + 7, F.T + 20, 't = ln a', '#475569', { size: 13.5, weight: 750 });
  s += txt(F.X(t) + 8, F.Y(ft) + 20, `f(t) = ${fmt(ft,2)}`, '#475569', { size: 12.5, weight: 650 });

  s += circleEl(F.X(x1), y0, 5.5, '#ef4444');
  s += circleEl(F.X(x2), y0, 5.5, '#059669');
  s += txt(F.X(x1), y0 - 13, 'x₁', '#b91c1c', { size: 14, weight: 800, anchor: 'middle' });
  s += txt(F.X(x2), y0 - 13, 'x₂', '#047857', { size: 14, weight: 800, anchor: 'middle' });

  s += txt(F.X(x1) - 8, y0 + 25, fmt(x1,2), '#b91c1c', { size: 11.5, weight: 650, anchor: 'end' });
  s += txt(F.X(x2) + 8, y0 + 25, fmt(x2,2), '#047857', { size: 11.5, weight: 650, anchor: 'start' });

  if (step === 3) {
    const u = t - x1;
    const v = x2 - t;
    const yseg = Math.min(F.B - 16, y0 + 46);
    s += lineEl(F.X(x1), y0, F.X(x1), yseg, '#c4b5fd', 1.2, '3 4');
    s += lineEl(F.X(t), y0, F.X(t), yseg, '#c4b5fd', 1.2, '3 4');
    s += lineEl(F.X(x2), y0, F.X(x2), yseg, '#bae6fd', 1.2, '3 4');
    s += lineEl(F.X(x1), yseg, F.X(t), yseg, '#8b5cf6', 8);
    s += lineEl(F.X(t), yseg, F.X(x2), yseg, '#0891b2', 8);
    s += txt((F.X(x1) + F.X(t)) / 2, yseg - 10, 'u = t − x₁', '#6d28d9', { size: 12.5, weight: 800, anchor: 'middle' });
    s += txt((F.X(t) + F.X(x2)) / 2, yseg + 23, 'v = x₂ − t', '#0e7490', { size: 12.5, weight: 800, anchor: 'middle' });
    s += txt(F.L + 18, F.B - 18, `u = ${fmt(u,2)}，v = ${fmt(v,2)}，二者都大于 0`, '#334155', { size: 13.5, weight: 700 });
  }

  s += txt(F.X(0) + 8, y0 - 8, 'O', '#64748b', { size: 12, weight: 700 });
  s += txt(F.R - 8, F.B + 34, 'x', '#475569', { size: 14, weight: 700, anchor: 'end' });
  s += txt(F.L - 44, F.T + 17, 'y', '#475569', { size: 14, weight: 700, anchor: 'middle' });

  let side = '';
  if (step === 2) {
    side = `
      <div class="kicker">第 (2) 问 (i) · 两根条件</div>
      <h2>极小值必须掉到横轴下方</h2>
      <div class="formula-box">
        <div class="formula-line">f′(x) = e<sup>x</sup> − a</div>
        <div class="formula-line">a&gt;0 时，唯一极小点 t = ln a</div>
        <div class="formula-line">f(t) = a − a ln a − 3 = h(a)</div>
        <div class="formula-line">h(a)=a(1−ln a)−3，h′(a)=−ln a</div>
        <div class="formula-line">a&gt;0 时 h 在 a=1 取最大值 h(1)=−2</div>
        <div class="formula-line highlight">所以 f(t)=h(a) ≤ −2 &lt; 0</div>
      </div>
      <p><b>a≤0</b> 时 f′(x)=e<sup>x</sup>−a&gt;0，f 单调，至多一个零点，不可能有两个零点。</p>
      <p><b>a&gt;0</b> 时 f 先减后增，且两端都趋向 +∞；极小值又小于 0，所以从左、右各穿过横轴一次，恰有两个零点。</p>
      <div class="readout">
        <div class="readout-row"><span>当前 a</span><b>${fmt(a,2)}</b></div>
        <div class="readout-row"><span>极小点 t</span><b>${fmt(t,2)}</b></div>
        <div class="readout-row"><span>f(t)</span><b>${fmt(ft,2)}</b></div>
        <div class="readout-row"><span>零点个数</span><b class="ok">2</b></div>
      </div>
      <p class="note">滑块展示 a∈[0.2,5] 的示例；完整可行范围是 a&gt;0，a≤0 的情况已由单调性排除。</p>
      <div class="conclusion">(2)(i) a 的取值范围：a &gt; 0。</div>
    `;
  } else {
    const u = t - x1;
    const v = x2 - t;
    side = `
      <div class="kicker">第 (2) 问 (ii) · 移位</div>
      <h2>以极小点为基准，把两根写成 t−u 与 t+v</h2>
      <div class="formula-box">
        <div class="formula-line">t = ln a，x₁ = t − u，x₂ = t + v，u,v&gt;0</div>
        <div class="formula-line">e<sup>−u</sup> = t − u + 3/a</div>
        <div class="formula-line">e<sup>v</sup> = t + v + 3/a</div>
        <div class="formula-line highlight">相减得：e<sup>v</sup> − e<sup>−u</sup> = u + v</div>
      </div>
      <p>要证 3e<sup>x₁</sup>+e<sup>x₂</sup>&gt;3a，两边除以 a（a&gt;0），等价于证明：</p>
      <div class="formula-line highlight" style="margin-top:8px">3e<sup>−u</sup> + e<sup>v</sup> &gt; 3</div>
      <div class="readout">
        <div class="readout-row"><span>u = t − x₁</span><b>${fmt(u,2)}</b></div>
        <div class="readout-row"><span>v = x₂ − t</span><b>${fmt(v,2)}</b></div>
        <div class="readout-row"><span>x₁</span><b>${fmt(x1,2)}</b></div>
        <div class="readout-row"><span>x₂</span><b>${fmt(x2,2)}</b></div>
      </div>
      <p class="note">图中两段彩色横条就是 u 与 v；它们把“两个零点”转化成两个正数 u、v 的关系。</p>
      <p class="note">滑块只演示 a∈[0.2,5] 的示例；a 的完整可行范围仍是 a&gt;0。</p>
    `;
  }
  return { svg: s, side };
}

function renderLemma(){
  const r = state.r;
  const phi = rr => ((rr + 3) * Math.log(rr)) / (3 * (rr - 1));
  const cfg = {
    xMin: 1, xMax: 8, yMin: 0.98, yMax: 1.36,
    xTicks: [1,2,3,4,5,6,7,8],
    yTicks: [1, 1.1, 1.2, 1.3]
  };
  const F = frame(cfg);
  let s = F.svg;

  s += txt(F.L + 8, F.T - 14, '证明等价于 φ(r) > 1（r>1）', '#0f172a', { size: 16, weight: 800, stroke: false });

  s += `<rect x="${F.L}" y="${F.T}" width="${F.W}" height="${Math.max(0, F.Y(1)-F.T)}" fill="#10b981" opacity="0.055" clip-path="url(#plotClip)"/>`;
  s += lineEl(F.L, F.Y(1), F.R, F.Y(1), '#10b981', 2, '7 6');
  s += txt(F.R - 8, F.Y(1) - 8, '目标下界 1', '#047857', { size: 13, weight: 750, anchor: 'end' });

  s += pathFor(phi, F.X, F.Y, 1.02, 8, 340,
    'stroke="#2563eb" stroke-width="3.2" clip-path="url(#plotClip)"');

  const y = phi(r);
  s += lineEl(F.X(r), F.Y(1), F.X(r), F.Y(y), '#f59e0b', 1.5, '4 4');
  s += circleEl(F.X(r), F.Y(y), 6, '#f59e0b');
  const labelOnLeft = r > 5.7;
  const labelX = F.X(r) + (labelOnLeft ? -10 : 10);
  const labelAnchor = labelOnLeft ? 'end' : 'start';
  const labelY = r < 1.5 ? F.Y(y) + 24 : F.Y(y) - 9;
  s += txt(labelX, labelY, `r = ${fmt(r,2)}，φ(r) = ${fmt(y,3)}`, '#b45309', { size: 13, weight: 800, anchor: labelAnchor });

  s += svgBadge(F.R - 188, F.T + 38, 'φ(r) > 1', '#166534', '#dcfce7');
  s += txt(F.X(2.2) + 20, F.Y(phi(2.2)) - 25, 'φ(r)', '#1d4ed8', { size: 15, weight: 800 });

  s += txt(F.R - 8, F.B + 34, 'r', '#475569', { size: 14, weight: 700, anchor: 'end' });
  s += txt(F.L - 44, F.T + 17, 'φ', '#475569', { size: 14, weight: 700, anchor: 'middle' });

  const p = Math.log(r) / (r - 1);
  const z = p * r;

  const side = `
    <div class="kicker">第 (2) 问 (ii) · 证明</div>
    <h2>把所有关系集中到一个参数 r 上</h2>
    <div class="formula-box">
      <div class="formula-line">令 p = e<sup>−u</sup>，z = e<sup>v</sup>，r = z/p = e<sup>u+v</sup> &gt; 1</div>
      <div class="formula-line">z − p = u + v = ln r</div>
      <div class="formula-line">所以 p(r−1) = ln r ⇒ p = ln r/(r−1)，z = pr</div>
      <div class="formula-line highlight">3p + z &gt; 3 ⇔ (r+3)ln r &gt; 3(r−1)</div>
    </div>
    <div class="mini-proof">
      记 H(r) = (r+3)ln r − 3(r−1)。<br>
      H(1)=0；H′(r)=ln r + 3/r − 2；H″(r)=(r−3)/r²。
      <div style='display:flex;margin:8px 0;border:1px solid #fcd34d;border-radius:8px;overflow:hidden;text-align:center;font-size:12px;line-height:1.5'>
        <div style='flex:2;background:#ecfdf5;padding:6px;color:#047857;font-weight:750'>1 &lt; r &lt; 3<br><span style='font-weight:500'>H′ 递减，但 H′&gt;H′(3)&gt;0</span></div>
        <div style='flex:3;background:#eff6ff;padding:6px;color:#1d4ed8;font-weight:750'>r &gt; 3<br><span style='font-weight:500'>H′ 递增，H′&gt;H′(3)&gt;0</span></div>
      </div>
      由 H″ 的符号，H′ 在 (1,3) 递减、在 (3,+∞) 递增；最小值 H′(3)=ln3−1&gt;0。所以 H′(r)&gt;0，H 在 r&gt;1 上递增，H(r)&gt;H(1)=0。
    </div>
    <p>所以对本题中由两个零点得到的 r&gt;1，都有 φ(r)&gt;1，从而原不等式严格成立。</p>
    <div class="readout">
      <div class="readout-row"><span>当前 r</span><b>${fmt(r,2)}</b></div>
      <div class="readout-row"><span>p = e<sup>−u</sup></span><b>${fmt(p,3)}</b></div>
      <div class="readout-row"><span>z = e<sup>v</sup></span><b>${fmt(z,3)}</b></div>
      <div class="readout-row"><span>3p + z</span><b class="ok">${fmt(3*p+z,3)} &gt; 3</b></div>
    </div>
    <p class="note">证明中的 r = e<sup>u+v</sup> = e<sup>x₂−x₁</sup> &gt; 1，是辅助参数；对任意 r&gt;1 都有 φ(r)&gt;1。滑块只展示 r&gt;1 的一段示例范围，并不表示原题中可单独调节 r。</p>
    <div class="conclusion">(2)(ii) 得证：3e<sup>x₁</sup> + e<sup>x₂</sup> &gt; 3a。</div>
  `;
  return { svg: s, side };
}

function updateTabs(){
  document.querySelectorAll('.step-btn').forEach(btn => {
    btn.classList.toggle('active', Number(btn.dataset.step) === state.step);
  });
}

function syncControls(){
  if (state.step <= 1) {
    sliderLabel.textContent = '参数 a（演示 0.2–1.8）';
    slider.min = '0.2';
    slider.max = '1.8';
    slider.step = '0.01';
    slider.value = String(state.a1);
    sliderValue.textContent = fmt(state.a1, 2);
    quickBtn.textContent = 'a=1 边界';
  } else if (state.step <= 3) {
    sliderLabel.textContent = '参数 a（演示 0.2–5）';
    slider.min = '0.2';
    slider.max = '5';
    slider.step = '0.01';
    slider.value = String(state.a2);
    sliderValue.textContent = fmt(state.a2, 2);
    quickBtn.textContent = '回到 a=1.5';
  } else {
    sliderLabel.textContent = '辅助参数 r（演示）';
    slider.min = '1.02';
    slider.max = '8';
    slider.step = '0.01';
    slider.value = String(state.r);
    sliderValue.textContent = fmt(state.r, 2);
    quickBtn.textContent = 'r=3 示例';
  }
}

function updateAnswers(){
  document.getElementById('ans1').classList.toggle('locked', state.step < 1);
  document.getElementById('ans2').classList.toggle('locked', state.step < 2);
  document.getElementById('ans3').classList.toggle('locked', state.step < 4);
}

function render(){
  updateTabs();
  let data;
  if (state.step <= 1) {
    state.a1 = clamp(state.a1, 0.2, 1.8);
    data = renderPart1(state.step);
  } else if (state.step <= 3) {
    state.a2 = clamp(state.a2, 0.2, 5);
    data = renderPart2(state.step);
  } else {
    state.r = clamp(state.r, 1.02, 8);
    data = renderLemma();
  }
  svgEl.innerHTML = data.svg;
  sideEl.innerHTML = data.side;
  syncControls();
  updateAnswers();
}

document.querySelectorAll('.step-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    state.step = Number(btn.dataset.step);
    render();
  });
});

slider.addEventListener('input', () => {
  const v = Number(slider.value);
  if (state.step <= 1) state.a1 = v;
  else if (state.step <= 3) state.a2 = v;
  else state.r = v;
  render();
});

quickBtn.addEventListener('click', () => {
  if (state.step <= 1) state.a1 = 1;
  else if (state.step <= 3) state.a2 = 1.5;
  else state.r = 3;
  render();
});

resetBtn.addEventListener('click', () => {
  if (state.step <= 1) state.a1 = DEFAULTS.a1;
  else if (state.step <= 3) state.a2 = DEFAULTS.a2;
  else state.r = DEFAULTS.r;
  render();
});

render();
</script>
</body>
</html>
